package com.ethk3.novaonepro.strategyv2;
import java.io.*;
import java.lang.reflect.*;
import java.nio.*;
import java.util.*;

/** Independent Bayesian responsibilities, actual sufficient-statistic changes and old codec provenance. */
public final class R26StatisticalDiagnosticsTest {
    static void check(boolean ok,String why){if(!ok)throw new AssertionError(why);}
    static OnlineModelsSU2.Hmm kernel(FamilyF08KernelR26 model)throws Exception{Field f=FamilyF08KernelR26.class.getDeclaredField("model");f.setAccessible(true);return (OnlineModelsSU2.Hmm)f.get(model);}
    static FamilyF08KernelR26 make(int k,boolean memory){return k==0?new FamilyF08KernelR26():new FamilyF08KernelR26(k,memory);}
    static byte[] save(FamilyF08KernelR26 model)throws IOException{ByteArrayOutputStream b=new ByteArrayOutputStream();model.write(new DataOutputStream(b));return b.toByteArray();}
    static FamilyF08KernelR26 restore(int k,boolean memory,byte[] bytes)throws IOException{FamilyF08KernelR26 model=make(k,memory);model.read(new DataInputStream(new ByteArrayInputStream(bytes)));return model;}
    static byte[] legacy(byte[] bytes)throws IOException{check(ByteBuffer.wrap(bytes).getInt()==0x26080002,"New HMM state codec missing");int k=ByteBuffer.wrap(bytes).getInt(4);byte[] body=Arrays.copyOfRange(bytes,10,bytes.length-9-4-k*k*8);if(bytes[9]!=0)return body;ByteArrayOutputStream b=new ByteArrayOutputStream();DataOutputStream out=new DataOutputStream(b);out.writeInt(0x26080001);out.writeInt(k);out.writeBoolean(bytes[8]!=0);out.write(body);return b.toByteArray();}
    static int[] draw(Random random){int[] d=new int[10];for(int i=0;i<10;i++)d[i]=i+1;for(int i=9;i>0;i--){int q=random.nextInt(i+1),v=d[q];d[q]=d[i];d[i]=v;}return d;}
    static double loss(OnlineModelsSU2.Hmm model,double[] old,int[] target){double[] pi=new double[model.K];for(int k=0;k<model.K;k++)for(int q=0;q<model.K;q++)pi[k]+=old[q]*model.A[q*model.K+k];double value=0;for(int p=0;p<10;p++){double mass=0;for(int k=0;k<model.K;k++)mass+=pi[k]*model.E[k*100+p*10+target[p]-1];value-=Math.log(mass)/10;}return value;}
    public static void main(String[] args)throws Exception{
        double maximumPosteriorError=0,maximumStatisticError=0;int graphs=0;
        for(int k=0;k<=6;k++){if(k==1)continue;for(boolean memory:k==0?new boolean[]{true}:new boolean[]{false,true}){
            graphs++;Random random=new Random(260808+k);FamilyF08KernelR26 model=make(k,memory);for(int i=0;i<12;i++)model.update(draw(random));check(!(Object.class.cast(model) instanceof TrainingDiagnosticsR26),"EM update masqueraded as an applied gradient");byte[] originalBytes=save(model);OnlineModelsSU2.Hmm old=kernel(model);double[] emissions=old.E.clone(),posterior=old.a.clone(),expectedPosterior=new double[old.K];int[] target=draw(random);double mass=0;
            // Product-space Bayes independently checks the kernel's tempered log-space filter.
            for(int s=0;s<old.K;s++){double pi=0,likelihood=1;for(int q=0;q<old.K;q++)pi+=posterior[q]*old.A[q*old.K+s];for(int p=0;p<10;p++)likelihood*=emissions[s*100+p*10+target[p]-1];expectedPosterior[s]=pi*Math.pow(likelihood,old.temper);mass+=expectedPosterior[s];}for(int s=0;s<old.K;s++)expectedPosterior[s]/=mass;
            double[] expectedEmission=emissions.clone();for(int s=0;s<old.K;s++)for(int p=0;p<10;p++)for(int n=0;n<10;n++)expectedEmission[s*100+p*10+n]=(1-old.lr*expectedPosterior[s])*emissions[s*100+p*10+n]+(target[p]==n+1?old.lr*expectedPosterior[s]:0);
            double before=loss(old,posterior,target);model.update(target);OnlineModelsSU2.Hmm next=kernel(model);StatisticalTrainingDiagnosticsR26.Step step=model.lastStatisticalTrainingStep();check(step.update==13&&Math.abs(step.lossBefore-before)<1e-12&&Math.abs(step.lossAfter-loss(next,posterior,target))<1e-12,"Predictive losses changed the fixed pre-label posterior");double squared=0;
            for(int s=0;s<old.K;s++){double error=Math.abs(next.a[s]-expectedPosterior[s]);maximumPosteriorError=Math.max(maximumPosteriorError,error);check(error<1e-12,"Filtered Bayesian responsibility differs");}for(int i=0;i<emissions.length;i++){double error=Math.abs(next.E[i]-expectedEmission[i]);maximumStatisticError=Math.max(maximumStatisticError,error);check(error<1e-12,"Expected emission-frequency update differs");double d=next.E[i]-emissions[i];squared+=d*d;}check(Math.abs(step.statisticDeltaNorm-Math.sqrt(squared))<1e-13&&step.statisticDeltaNorm==step.parameterDeltaNorm&&step.statisticName.equals("POSTERIOR_UPDATED_CATEGORICAL_EMISSION_FREQUENCY_ESTIMATES"),"Actual sufficient-statistic change not measured");
            FamilyF08KernelR26 original=restore(k,memory,originalBytes);original.update(draw(random));check(step.inputHash.equals(original.lastStatisticalTrainingStep().inputHash),"Input hash observed target");FamilyF08KernelR26 copy=restore(k,memory,save(model));check(copy.lastStatisticalTrainingStep()==null,"Restore fabricated statistical work");int[] future=draw(random);model.update(future);copy.update(future);check(Arrays.equals(save(model),save(copy)),"Restored next EM update differs");long count=model.completedTrainingUpdates();double[] learned=kernel(model).E.clone();model.resetTemporalContext();check(model.completedTrainingUpdates()==count&&model.lastStatisticalTrainingStep()==null&&Arrays.equals(learned,kernel(model).E),"Gap erased learned sufficient statistics or counter");copy=restore(k,memory,save(model));future=draw(random);model.update(future);copy.update(future);check(Arrays.equals(save(model),save(copy)),"Gap restore and next update differ");
            byte[] oldBytes=legacy(save(model));FamilyF08KernelR26 migrated=restore(k,memory,oldBytes);check(migrated.completedTrainingUpdates()==0&&migrated.optimizerProtocol().endsWith("UNKNOWN_PRIOR_UPDATES_COUNTED_SINCE_IMPORT"),"Old checkpoint fabricated a missing training clock");check(Arrays.equals(oldBytes,legacy(save(migrated))),"Old default or graph checkpoint lost full numbers");future=draw(random);model.update(future);migrated.update(future);check(Arrays.equals(legacy(save(model)),legacy(save(migrated)))&&migrated.completedTrainingUpdates()==1,"Old codec changed subsequent numerical execution");
            byte[] unchanged=save(model);for(int kind=0;kind<4;kind++){byte[] bad=unchanged.clone();if(kind==0)Arrays.fill(bad,14,22,(byte)0xff);if(kind==1)Arrays.fill(bad,bad.length-9,bad.length-1,(byte)0xff);if(kind==2)bad[bad.length-1]=2;if(kind==3)bad=Arrays.copyOf(bad,bad.length-2);try{model.read(new DataInputStream(new ByteArrayInputStream(bad)));throw new AssertionError("Bad HMM checkpoint accepted");}catch(IOException expected){}check(Arrays.equals(unchanged,save(model)),"Rejected restore damaged retained numerical state");}
            boolean canceled=false;for(int operations:new int[]{1,2,100}){model.read(new DataInputStream(new ByteArrayInputStream(unchanged)));ExecutionBudgetR26.enter(new BudgetTokenSU1(30000,operations,()->false));try{model.update(target);}catch(BudgetTokenSU1.Yield expected){canceled=true;check(Arrays.equals(unchanged,save(model))&&model.lastStatisticalTrainingStep()==null,"Interrupted EM update partially committed");}finally{ExecutionBudgetR26.leave();}}check(canceled,"Staged EM interruption not exercised");
            if(args.length>0&&k==0)java.nio.file.Files.write(java.nio.file.Paths.get(args[0]),save(model));
        }}
        System.out.println("R26_STATISTICAL_DIAGNOSTICS_PASS|graphs="+graphs+"|maximumPosteriorError="+maximumPosteriorError+"|maximumEmissionStatisticError="+maximumStatisticError+"|properFixedInputMarginalNll=true|sufficientStatisticsNotFakeGradients=true|defaultAndGraphOldHistoryUnknown=true|fullTransitionMatrixSaved=true|restoreNextGapCancelAtomic=true|scope=SYNTHETIC_KERNEL_NOT_NATURAL_QUALITY");
    }
}
